package smartcampus;
import java.awt.*;import java.sql.*;
public class Violation extends Panel{TextField plate=UI.field(""),type=UI.field("Unauthorized Parking"),fine=UI.field("200");TextArea out=new TextArea();Violation(Frame f){setLayout(new BorderLayout(8,8));setBackground(UI.BG);add(UI.label("VIOLATIONS + FINES",22,UI.NAVY),BorderLayout.NORTH);Panel p=new Panel(new GridLayout(0,2,5,5));p.add(new Label("Vehicle Plate"));p.add(plate);p.add(new Label("Violation Type"));p.add(type);p.add(new Label("Fine"));p.add(fine);Button b=UI.button("RECORD VIOLATION",UI.RED);p.add(b);add(p,BorderLayout.WEST);out.setEditable(false);add(out,BorderLayout.CENTER);b.addActionListener(e->save());}void save(){try(Connection c=DB.get()){PreparedStatement p=c.prepareStatement("select vehicle_id from vehicles where plate_number=?");p.setString(1,plate.getText());ResultSet r=p.executeQuery();if(!r.next()){out.setText("Vehicle not found");return;}p=c.prepareStatement("insert into violations(vehicle_id,violation_type,fine_amount,status) values(?,?,?,'Unpaid')");p.setInt(1,r.getInt(1));p.setString(2,type.getText());p.setDouble(3,Double.parseDouble(fine.getText()));p.executeUpdate();out.setText("Violation recorded successfully.");}catch(Exception e){out.setText(e.getMessage());}}}
